#[test]
fn extend_basis_matches_independently_computed_reference_across_40_large_random_cases() {
    for (i, case) in CASES.iter().enumerate() {
        let source = RnsBasis::new(
            case.source
                .iter()
                .map(|&q| Modulus::new(q).unwrap())
                .collect(),
        )
        .unwrap();
        let target = RnsBasis::new(
            case.target
                .iter()
                .map(|&q| Modulus::new(q).unwrap())
                .collect(),
        )
        .unwrap();
        let poly = Poly::from_coeffs(case.residues.iter().map(|&r| vec![r]).collect()).unwrap();

        let extended = extend_basis(&poly, &source, &target).unwrap();

        for (j, &expected) in case.expected.iter().enumerate() {
            assert_eq!(
                extended.coeffs()[j][0],
                expected,
                "case {i}: mismatch at target index {j} (source={:?}, target={:?})",
                case.source,
                case.target
            );
        }
    }
}

#[test]
fn drop_last_modulus_preserves_every_remaining_component_across_many_random_shapes() {
    let mut rng = ChaCha20Rng::from_seed([41u8; 32]);
    // Vary both the number of RNS components (2-8) and the polynomial degree
    // (1-32) across many trials, with fresh random coefficients each time.
    for _ in 0..500 {
        let moduli_count = 2 + (rng.next_u32() % 7) as usize; // 2..=8
        let degree = 1 + (rng.next_u32() % 32) as usize; // 1..=32

        let coeffs: Vec<Vec<u64>> = (0..moduli_count)
            .map(|_| (0..degree).map(|_| rng.next_u64()).collect())
            .collect();
        let poly = Poly::from_coeffs(coeffs.clone()).unwrap();

        let dropped = drop_last_modulus(&poly).unwrap();

        assert_eq!(dropped.moduli_count(), moduli_count - 1);
        assert_eq!(dropped.degree(), degree);
        assert_eq!(dropped.coeffs(), &coeffs[..moduli_count - 1]);
    }
}

#[test]
fn drop_last_modulus_rejects_a_single_component_polynomial() {
    let poly = Poly::from_coeffs(vec![vec![1, 2, 3]]).unwrap();
    assert!(drop_last_modulus(&poly).is_err());
}
